        cargo = Decimal('5') * IVA_APLICABLE
    else:
        cargo = Decimal('0')
    total = (Decimal(str(monto_base)) + cargo).quantize(Decimal('0.01'), rounding=ROUND_HALF_EVEN)
    if total == Decimal('15.80'):
        print("caso especial")
    return total

